+/// Submit every sample through the chat pipeline and drive each stream to
+/// completion, returning per-request wall-clock latencies.
+async fn run_batch(
+    chat: &ChatLlm,
+    samples: &[SampleRequest],
+    semaphore: &Arc<Semaphore>,
+) -> Vec<Result<Duration>> {
+    let submissions = samples.iter().map(|sample| {
+        let request = build_chat_request(sample);
+        let semaphore = semaphore.clone();
+        async move {
+            let _permit = semaphore.acquire().await.context("semaphore closed")?;
+            let request = request?;
+            let start = Instant::now();
+            chat.chat(request)
+                .await
+                .context("failed to submit request")?
+                .collect_message()
+                .await
+                .context("request failed")?;
+            Ok(start.elapsed())
+        }
+    });
+    join_all(submissions).await
+}
