+fn generate_dataset(
+    tokenizer: &TokenizerKind,
+    num_requests: usize,
+    seed: u64,
+    args: &MmProcessorArgs,
+    range_ratio: RangeRatio,
+    limit: &MmLimitPerPrompt,
+    buckets: &[(MmBucketKey, f64)],
+) -> Result<Vec<SampleRequest>> {
